#include <bits/stdc++.h>
#define FOR(i,j,n) for(int i=j;i<=n;i++)
#define REV(i,j,n) for(int i=n;i>=j;i--)
#define ull unsigned long long
#define MAXN 250010
using namespace std;
namespace io {
	const int BUFFER_SIZE = (1<<19)+1;
	char inputBuffer[BUFFER_SIZE], *inputPtr, *inputEnd, outputBuffer[BUFFER_SIZE], *outputPtr=outputBuffer, *outputEnd=outputBuffer+BUFFER_SIZE-1, ch, temp[55];
	int flag, type;
	char gc() {
		if(inputPtr==inputEnd) {
			inputEnd=(inputBuffer=ibuf)+fread(ibuf,1,BUFFER_SIZE,stdin);
			return inputPtr==inputEnd ? EOF : *inputPtr++;
		}
		return *inputPtr++;
	}
	template<class T> void read(T& x) {
		flag=1; ch=gc();
		while(ch<'0'||ch>'9') { if(ch=='-') flag=-1; ch=gc(); }
		x=0;
		while(ch>='0'&&ch<='9') { x=x*10+(ch&15); ch=gc(); }
		x*=flag;
	}
}
using namespace io;
int n,k,p;
int bits[MAXN];
ull x[26][MAXN], factorial[MAXN], invFactorial[MAXN], base, result;
ull power(ull baseVal, int exp=p-2) {
	ull res=1;
	while(exp) {
		if(exp&1) res=res*baseVal%p;
		baseVal=baseVal*baseVal%p;
		exp>>=1;
	}
	return res;
}
ull dfs(int depth, int num) {
	if(bits[num]<depth) return 0;
	if(depth==1) return x[depth][num];
	if(x[depth][num]) return x[depth][num];
	int count=0;
	for(int mask=num&(num-1); mask; mask=num&(mask-1))
		if(bits[mask]>=depth-1) {
			x[depth][num]+=dfs(depth-1,mask)*x[num^mask][num];
			if(++count==18) { count=0; x[depth][num]%=p; }
		}
	x[depth][num]%=p;
	return x[depth][num];
}
ull comb(int n, int m) {
	return factorial[n]*invFactorial[m]%p*invFactorial[n-m]%p;
}
int main() {
	#ifndef ONLINE_JUDGE
	freopen("255x.in","r",stdin);
	freopen("255x.out","w",stdout);
	#endif
	read(n); read(k); read(p);
	FOR(i,1,n) bits[i]=bits[i>>1]+(i&1);
	base=power(k,n);
	if(n&1) {
		printf("%d\n", (int)base);
		return 0;
	}
	int limit=min(k, bits[n]);
	factorial[0]=1;
	FOR(i,1,n) factorial[i]=factorial[i-1]*i%p;
	invFactorial[n]=power(factorial[n]);
	REV(i,1,n-1) invFactorial[i]=invFactorial[i+1]* (i+1)%p;
	result=0;
	REV(i,1,limit) result+=comb(k,i)*dfs(i,n);
	result=(base - result%p*factorial[n]%p + p)%p;
	printf("%lld\n", result);
	return 0;
}
